#!/usr/bin/env bash
# ============================================================
# ZEN Before/After Inference Test
# Purpose: Demonstrate that ZEN-recovered patches enable
#          inference with custom model layers.
#
# Prerequisites:
#   - run_zen_demo.sh completed successfully
#   - Patch file generated by CMR Recovery
# ============================================================
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ZEN_DIR="$ROOT/third_party/ZEN"
YOLO_DIR="$ZEN_DIR/Models/YoloV5s/yolov5"
WEIGHTS="$ZEN_DIR/Models/YoloV5s/yolov5-CBAM-Involution-Visdrone/visdrone.pt"
RESULTS="$ROOT/results/zen"

mkdir -p "$RESULTS/without-patch" "$RESULTS/with-patch" "$ROOT/logs/zen"

echo "=========================================="
echo " ZEN Before/After Inference Test"
echo " $(date '+%Y-%m-%d %H:%M:%S')"
echo "=========================================="

cd "$YOLO_DIR"

# Test 1: WITHOUT patch (expected to fail)
echo ""
echo "→ Test 1: Running inference WITHOUT patch..."
echo "  (Expected: failure due to missing custom layers)"
if python detect.py --weights "$WEIGHTS" \
  2>&1 | tee "$ROOT/logs/zen/inference-without-patch.log"; then
  echo "  ⚠️  Unexpectedly succeeded without patch"
else
  echo "  ✅ Failed as expected (custom layers missing)"
fi

# Test 2: WITH ZEN-recovered patch
echo ""
echo "→ Test 2: Running inference WITH ZEN patch..."

# Find the generated patch file
PATCH=$(find "$ZEN_DIR" -name "pickle_dict_4009375_3_8_18_yolov5-involution.pkl" \
  -type f 2>/dev/null | head -1)

if [ -z "$PATCH" ]; then
  echo "  ❌ Patch file not found. Run run_zen_demo.sh first."
  exit 1
fi

echo "  Using patch: $PATCH"
python detect.py --weights "$WEIGHTS" --patch "$PATCH" \
  2>&1 | tee "$ROOT/logs/zen/inference-with-patch.log"

echo ""
echo "  ✅ Inference with ZEN patch succeeded!"

# Copy output images for evidence
if [ -d "runs/detect" ]; then
  cp -r runs/detect/exp* "$RESULTS/with-patch/" 2>/dev/null || true
  echo "  📸 Detection outputs saved to $RESULTS/with-patch/"
fi

echo ""
echo "=========================================="
echo " ZEN Before/After Test COMPLETED"
echo " $(date '+%Y-%m-%d %H:%M:%S')"
echo "=========================================="
